-- Share links, invitations, collaborators, the public shared-ledger endpoint, and imports.
-- Tokens are generated by the server (32 random bytes, base64url). Only a SHA-256 hash is used
-- for lookup; an AES-GCM ciphertext (key held by the app server, never the database) lets the
-- owner copy the link again later.

create or replace function app.token_hash(p_token text) returns text
language sql immutable set search_path = '' as $$
  select encode(sha256(convert_to(p_token, 'UTF8')), 'hex')
$$;

create or replace function app.require_token(p_token text) returns void
language plpgsql immutable set search_path = '' as $$
begin
  if p_token is null or p_token !~ '^[A-Za-z0-9_-]{32,128}$' then
    raise exception 'Link is not valid' using errcode = '22023';
  end if;
end $$;

-- ---------------------------------------------------------------------------------------------
-- Share links (read-only public statements)
-- ---------------------------------------------------------------------------------------------
create or replace function public.create_share_link(p_ledger uuid, p_token text, p_ciphertext text, p jsonb)
returns uuid
language plpgsql security definer set search_path = '' as $$
declare
  v public.ledgers;
  v_id uuid;
begin
  select * into v from public.ledgers where id = p_ledger for update;
  if not found then
    raise exception 'Ledger not found' using errcode = 'P0002';
  end if;
  perform app.require_write(v.workspace_id);
  perform app.require_token(p_token);
  -- Rotating: the previous link stops working immediately.
  update public.share_links set revoked_at = now() where ledger_id = p_ledger and revoked_at is null;
  insert into public.share_links (
    workspace_id, ledger_id, token_hash, token_ciphertext, token_hint, show_balance, show_running_balance,
    show_tax, show_reference, show_counterparty, expires_at, created_by)
  values (
    v.workspace_id, p_ledger, app.token_hash(p_token), p_ciphertext, right(p_token, 4),
    coalesce((p ->> 'show_balance')::boolean, true), coalesce((p ->> 'show_running_balance')::boolean, true),
    coalesce((p ->> 'show_tax')::boolean, false), coalesce((p ->> 'show_reference')::boolean, false),
    coalesce((p ->> 'show_counterparty')::boolean, true), nullif(p ->> 'expires_at', '')::timestamptz, app.uid())
  returning id into v_id;
  return v_id;
end $$;

create or replace function public.update_share_link(p_id uuid, p jsonb) returns void
language plpgsql security definer set search_path = '' as $$
declare
  s public.share_links;
begin
  select * into s from public.share_links where id = p_id for update;
  if not found then
    raise exception 'Link not found' using errcode = 'P0002';
  end if;
  perform app.require_write(s.workspace_id);
  update public.share_links set
    show_balance = coalesce((p ->> 'show_balance')::boolean, show_balance),
    show_running_balance = coalesce((p ->> 'show_running_balance')::boolean, show_running_balance),
    show_tax = coalesce((p ->> 'show_tax')::boolean, show_tax),
    show_reference = coalesce((p ->> 'show_reference')::boolean, show_reference),
    show_counterparty = coalesce((p ->> 'show_counterparty')::boolean, show_counterparty),
    expires_at = case when p ? 'expires_at' then nullif(p ->> 'expires_at', '')::timestamptz else expires_at end
  where id = p_id;
end $$;

create or replace function public.revoke_share_link(p_id uuid) returns void
language plpgsql security definer set search_path = '' as $$
declare
  s public.share_links;
begin
  select * into s from public.share_links where id = p_id for update;
  if not found then
    raise exception 'Link not found' using errcode = 'P0002';
  end if;
  perform app.require_write(s.workspace_id);
  update public.share_links set revoked_at = now() where id = p_id and revoked_at is null;
end $$;

-- Returns the encrypted token of the active link so the server can rebuild the URL for the owner.
create or replace function public.share_link_secret(p_ledger uuid) returns text
language plpgsql stable security definer set search_path = '' as $$
begin
  if not app.can_write(app.ledger_workspace(p_ledger)) then
    return null;
  end if;
  return (select token_ciphertext from public.share_links
          where ledger_id = p_ledger and revoked_at is null and (expires_at is null or expires_at > now()));
end $$;

-- Public, read-only statement for a share token. Returns null for unknown, revoked or expired
-- links (no distinction, to avoid giving out hints). Exposes no database ids, notes, attachments,
-- workspace details or other ledgers. Fields are filtered by the link's settings.
create or replace function public.get_shared_ledger(p_token text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  s public.share_links;
  l public.ledgers;
  v_contractor text;
  v_rows jsonb;
  v_people jsonb;
  v_expenses jsonb;
  v_settlements jsonb;
begin
  if p_token is null or p_token !~ '^[A-Za-z0-9_-]{32,128}$' then
    return null;
  end if;
  select * into s from public.share_links
  where token_hash = app.token_hash(p_token) and revoked_at is null and (expires_at is null or expires_at > now());
  if not found then
    return null;
  end if;
  select * into l from public.ledgers where id = s.ledger_id;
  select name into v_contractor from public.contractors where id = l.contractor_id;

  if s.last_accessed_at is null or s.last_accessed_at < now() - interval '5 minutes' then
    update public.share_links set last_accessed_at = now() where id = s.id;
  end if;

  if l.ledger_type = 'personal' then
    select coalesce(jsonb_agg(jsonb_build_object('key', p.position, 'name', p.display_name) order by p.position), '[]'::jsonb)
      into v_people from public.ledger_participants p where p.ledger_id = l.id;
    select coalesce(jsonb_agg(jsonb_build_object(
        'date', e.txn_date, 'description', e.description, 'total', e.total_amount, 'method', e.split_method,
        'category', e.category, 'created', e.created_at,
        'payers', (select jsonb_agg(jsonb_build_object('key', p.position, 'amount', py.amount_paid))
                   from public.shared_expense_payers py join public.ledger_participants p on p.id = py.participant_id
                   where py.shared_expense_id = e.id),
        'shares', (select jsonb_agg(jsonb_build_object('key', p.position, 'amount', sh.share_amount))
                   from public.shared_expense_shares sh join public.ledger_participants p on p.id = sh.participant_id
                   where sh.shared_expense_id = e.id))
        order by e.txn_date, e.created_at), '[]'::jsonb)
      into v_expenses from public.shared_expenses e where e.ledger_id = l.id and e.status = 'posted';
    select coalesce(jsonb_agg(jsonb_build_object(
        'date', st.txn_date, 'amount', st.amount, 'created', st.created_at,
        'from', (select position from public.ledger_participants where id = st.from_participant_id),
        'to', (select position from public.ledger_participants where id = st.to_participant_id))
        order by st.txn_date, st.created_at), '[]'::jsonb)
      into v_settlements from public.settlements st where st.ledger_id = l.id and st.status = 'posted';
  else
    select coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
        'voucher_no', t.voucher_no, 'seq', t.seq, 'date', t.txn_date, 'direction', t.direction,
        'amount', t.amount, 'kind', t.kind, 'is_cash', t.is_cash, 'affects_party', t.affects_party,
        'description', t.description,
        'counterparty', case when s.show_counterparty then t.counterparty end,
        'reference_no', case when s.show_reference then t.reference_no end,
        'tax', case when s.show_tax and d.transaction_id is not null then jsonb_build_object(
          'invoice_no', d.invoice_no, 'taxable_amount', d.taxable_amount, 'gst_type', d.gst_type,
          'gst_rate', d.gst_rate, 'cgst_amount', d.cgst_amount, 'sgst_amount', d.sgst_amount,
          'igst_amount', d.igst_amount, 'gst_amount', d.gst_amount, 'tds_rate', d.tds_rate,
          'tds_base', d.tds_base, 'tds_amount', d.tds_amount, 'gross_amount', d.gross_amount,
          'net_amount', d.net_amount) end))
        order by t.txn_date, t.seq), '[]'::jsonb)
      into v_rows
    from public.transactions t
    left join public.transaction_tax_details d on d.transaction_id = t.id
    where t.ledger_id = l.id and t.status = 'posted';
  end if;

  return jsonb_build_object(
    'ledger', jsonb_build_object(
      'name', l.name, 'ledger_type', l.ledger_type, 'perspective', l.perspective,
      'contractor_name', v_contractor,
      'opening_balance', case when s.show_balance then l.opening_balance end,
      'opening_balance_date', l.opening_balance_date,
      'last_activity_at', l.last_activity_at),
    'options', jsonb_build_object(
      'show_balance', s.show_balance, 'show_running_balance', s.show_running_balance,
      'show_tax', s.show_tax, 'show_reference', s.show_reference, 'show_counterparty', s.show_counterparty),
    'transactions', coalesce(v_rows, '[]'::jsonb),
    'participants', v_people,
    'shared_expenses', v_expenses,
    'settlements', v_settlements);
end $$;

-- Lightweight change marker used by the public page to poll cheaply.
create or replace function public.get_shared_ledger_version(p_token text) returns timestamptz
language sql stable security definer set search_path = '' as $$
  select l.last_activity_at
  from public.share_links s join public.ledgers l on l.id = s.ledger_id
  where p_token ~ '^[A-Za-z0-9_-]{32,128}$'
    and s.token_hash = app.token_hash(p_token) and s.revoked_at is null
    and (s.expires_at is null or s.expires_at > now())
$$;

-- ---------------------------------------------------------------------------------------------
-- Invitations: workspace members, or ledger-scoped collaborators / personal-ledger participants
-- An invitation link is single use and requires a signed-in account to accept.
-- ---------------------------------------------------------------------------------------------
create or replace function public.create_invitation(p_token text, p jsonb) returns uuid
language plpgsql security definer set search_path = '' as $$
declare
  v_scope text := p ->> 'scope';
  v_ws uuid;
  v_ledger uuid := nullif(p ->> 'ledger_id', '')::uuid;
  v_participant uuid := nullif(p ->> 'participant_id', '')::uuid;
  v_id uuid;
begin
  perform app.require_token(p_token);
  if v_scope = 'ledger' then
    v_ws := app.ledger_workspace(v_ledger);
    perform app.require_write(v_ws);
    if v_participant is not null and not exists (
        select 1 from public.ledger_participants where id = v_participant and ledger_id = v_ledger and user_id is null) then
      raise exception 'Choose a person in this ledger who has not joined yet' using errcode = '22023';
    end if;
  elsif v_scope = 'workspace' then
    v_ws := (p ->> 'workspace_id')::uuid;
    perform app.require_admin(v_ws);
    if p ->> 'role' not in ('admin', 'member', 'viewer') then
      raise exception 'Choose a role' using errcode = '22023';
    end if;
  else
    raise exception 'Choose who the invitation is for' using errcode = '22023';
  end if;

  insert into public.invitations (
    workspace_id, scope, ledger_id, participant_id, token_hash, email, role, can_create, can_edit_own,
    can_edit_all, can_attach, can_view_tax, expires_at, created_by)
  values (
    v_ws, v_scope, case when v_scope = 'ledger' then v_ledger end, v_participant, app.token_hash(p_token),
    app.clean_text(p ->> 'email', 200), case when v_scope = 'workspace' then p ->> 'role' end,
    coalesce((p ->> 'can_create')::boolean, false), coalesce((p ->> 'can_edit_own')::boolean, false),
    coalesce((p ->> 'can_edit_all')::boolean, false), coalesce((p ->> 'can_attach')::boolean, false),
    coalesce((p ->> 'can_view_tax')::boolean, false),
    now() + make_interval(days => least(greatest(coalesce((p ->> 'expires_in_days')::integer, 14), 1), 60)),
    app.uid())
  returning id into v_id;
  return v_id;
end $$;

create or replace function public.revoke_invitation(p_id uuid) returns void
language plpgsql security definer set search_path = '' as $$
declare
  i public.invitations;
begin
  select * into i from public.invitations where id = p_id for update;
  if not found then
    raise exception 'Invitation not found' using errcode = 'P0002';
  end if;
  perform app.require_write(i.workspace_id);
  update public.invitations set status = 'revoked' where id = p_id and status = 'pending';
end $$;

-- What the invite landing page may show before the visitor signs in.
create or replace function public.get_invitation_preview(p_token text) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare
  i public.invitations;
begin
  if p_token is null or p_token !~ '^[A-Za-z0-9_-]{32,128}$' then
    return null;
  end if;
  select * into i from public.invitations where token_hash = app.token_hash(p_token);
  if not found then
    return null;
  end if;
  return jsonb_build_object(
    'scope', i.scope,
    'status', case when i.status = 'pending' and i.expires_at <= now() then 'expired' else i.status end,
    'ledger_name', (select name from public.ledgers where id = i.ledger_id),
    'ledger_type', (select ledger_type from public.ledgers where id = i.ledger_id),
    'workspace_name', case when i.scope = 'workspace' then (select name from public.workspaces where id = i.workspace_id) end,
    'participant_name', (select display_name from public.ledger_participants where id = i.participant_id),
    'invited_by', (select display_name from public.workspace_members where workspace_id = i.workspace_id and user_id = i.created_by),
    'role', i.role,
    'permissions', jsonb_build_object('can_create', i.can_create, 'can_edit_own', i.can_edit_own,
      'can_edit_all', i.can_edit_all, 'can_attach', i.can_attach, 'can_view_tax', i.can_view_tax),
    'expires_at', i.expires_at);
end $$;

create or replace function public.accept_invitation(p_token text, p_display_name text, p_email text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  v_uid text := app.uid();
  i public.invitations;
  v_ledger_type text;
begin
  if v_uid is null then
    raise exception 'Sign in to accept this invitation' using errcode = '42501';
  end if;
  perform app.require_token(p_token);
  select * into i from public.invitations where token_hash = app.token_hash(p_token) for update;
  if not found or i.status <> 'pending' or i.expires_at <= now() then
    raise exception 'This invitation is no longer valid. Ask for a new link.' using errcode = '22023';
  end if;

  if i.scope = 'workspace' then
    if app.is_member(i.workspace_id) then
      raise exception 'You are already a member of this workspace' using errcode = '22023';
    end if;
    insert into public.workspace_members (workspace_id, user_id, role, display_name, email)
    values (i.workspace_id, v_uid, i.role, app.clean_text(p_display_name, 120), app.clean_text(p_email, 200));
  else
    if app.is_member(i.workspace_id) then
      raise exception 'You already have access to this ledger through its workspace' using errcode = '22023';
    end if;
    select ledger_type into v_ledger_type from public.ledgers where id = i.ledger_id;
    insert into public.ledger_collaborators (
      workspace_id, ledger_id, user_id, participant_id, display_name, email, can_create, can_edit_own,
      can_edit_all, can_attach, can_view_tax, invited_by)
    values (
      i.workspace_id, i.ledger_id, v_uid, i.participant_id, app.clean_text(p_display_name, 120),
      app.clean_text(p_email, 200), i.can_create, i.can_edit_own, i.can_edit_all, i.can_attach,
      i.can_view_tax, i.created_by)
    on conflict (ledger_id, user_id) do update set
      status = 'active', revoked_at = null, participant_id = coalesce(excluded.participant_id, public.ledger_collaborators.participant_id),
      can_create = excluded.can_create, can_edit_own = excluded.can_edit_own, can_edit_all = excluded.can_edit_all,
      can_attach = excluded.can_attach, can_view_tax = excluded.can_view_tax, invited_by = excluded.invited_by;
    if i.participant_id is not null then
      if exists (select 1 from public.ledger_participants where ledger_id = i.ledger_id and user_id = v_uid and id <> i.participant_id) then
        raise exception 'You are already a different person in this ledger' using errcode = '22023';
      end if;
      update public.ledger_participants set user_id = v_uid where id = i.participant_id and user_id is null;
    end if;
  end if;

  update public.invitations set status = 'accepted', accepted_by = v_uid, accepted_at = now() where id = i.id;
  return jsonb_build_object('scope', i.scope, 'workspace_id', i.workspace_id, 'ledger_id', i.ledger_id);
end $$;

create or replace function public.update_collaborator(p_id uuid, p jsonb) returns void
language plpgsql security definer set search_path = '' as $$
declare
  c public.ledger_collaborators;
begin
  select * into c from public.ledger_collaborators where id = p_id for update;
  if not found then
    raise exception 'Collaborator not found' using errcode = 'P0002';
  end if;
  perform app.require_write(c.workspace_id);
  update public.ledger_collaborators set
    can_create = coalesce((p ->> 'can_create')::boolean, can_create),
    can_edit_own = coalesce((p ->> 'can_edit_own')::boolean, can_edit_own),
    can_edit_all = coalesce((p ->> 'can_edit_all')::boolean, can_edit_all),
    can_attach = coalesce((p ->> 'can_attach')::boolean, can_attach),
    can_view_tax = coalesce((p ->> 'can_view_tax')::boolean, can_view_tax)
  where id = p_id;
end $$;

create or replace function public.revoke_collaborator(p_id uuid) returns void
language plpgsql security definer set search_path = '' as $$
declare
  c public.ledger_collaborators;
begin
  select * into c from public.ledger_collaborators where id = p_id for update;
  if not found then
    raise exception 'Collaborator not found' using errcode = 'P0002';
  end if;
  perform app.require_write(c.workspace_id);
  update public.ledger_collaborators set status = 'revoked', revoked_at = now() where id = p_id;
end $$;

-- ---------------------------------------------------------------------------------------------
-- Spreadsheet import: one batch, all rows or none.
-- ---------------------------------------------------------------------------------------------
create or replace function public.import_transactions(p jsonb) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  v_ledger_id uuid := (p ->> 'ledger_id')::uuid;
  v public.ledgers;
  v_batch uuid;
  v_row jsonb;
  v_txn uuid;
  v_kind text;
  v_amount numeric;
  v_direction text;
  v_count integer := 0;
  v_calc jsonb;
begin
  perform app.require_write(app.ledger_workspace(v_ledger_id));
  v := app.lock_ledger(v_ledger_id, false);
  if jsonb_typeof(p -> 'rows') <> 'array' or jsonb_array_length(p -> 'rows') = 0 then
    raise exception 'There are no rows to import' using errcode = '22023';
  end if;
  if jsonb_array_length(p -> 'rows') > 5000 then
    raise exception 'Import up to 5,000 rows at a time' using errcode = '22023';
  end if;
  if exists (select 1 from public.import_batches where ledger_id = v_ledger_id
             and file_hash = p ->> 'file_hash' and sheet_name = p ->> 'sheet_name') then
    raise exception 'This sheet from this file has already been imported into this ledger' using errcode = '23505';
  end if;

  insert into public.import_batches (workspace_id, ledger_id, file_name, file_hash, sheet_name, skipped_count, issues, created_by)
  values (v.workspace_id, v_ledger_id, coalesce(app.clean_text(p ->> 'file_name', 200), 'import.xlsx'), p ->> 'file_hash',
    coalesce(app.clean_text(p ->> 'sheet_name', 100), 'Sheet1'), coalesce((p ->> 'skipped_count')::integer, 0),
    coalesce(p -> 'issues', '[]'::jsonb), app.uid())
  returning id into v_batch;

  for v_row in select * from jsonb_array_elements(p -> 'rows') loop
    v_kind := case when nullif(v_row ->> 'amount', '') is null and v_row ? 'tax' then 'invoice' else 'regular' end;
    if v_kind = 'invoice' and v.ledger_type <> 'taxation' then
      raise exception 'Row %: bills with tax need a taxation ledger', v_row ->> 'row' using errcode = '22023';
    end if;
    v_direction := coalesce(nullif(v_row ->> 'direction', ''), 'in');
    v_amount := case when v_kind = 'invoice' then 0.01 else app.money(v_row ->> 'amount', 'Row ' || (v_row ->> 'row') || ' amount') end;
    v_txn := app.insert_txn(v_ledger_id, v.workspace_id, app.txn_date(v_row ->> 'txn_date'), v_direction, v_amount,
      v_kind, v_row, 'posted', 'import', 'imp:' || v_batch || ':' || (v_row ->> 'row'),
      null, v_batch, (v_row ->> 'row')::integer);
    if v_row ? 'tax' and jsonb_typeof(v_row -> 'tax') = 'object' and v.ledger_type = 'taxation' then
      v_calc := app.write_tax_details(v_txn, v.workspace_id, v_ledger_id, v.gst_mode, v_row -> 'tax');
      if v_kind = 'invoice' then
        update public.transactions set amount = (v_calc ->> 'net_amount')::numeric where id = v_txn;
      end if;
    end if;
    v_count := v_count + 1;
  end loop;

  update public.import_batches set imported_count = v_count where id = v_batch;
  return jsonb_build_object('batch_id', v_batch, 'imported', v_count);
end $$;
